def _make_lesson_content(course_id, module, title):
    course_name = COURSE_NAMES.get(course_id, course_id.replace('-', ' ').title())
    topic = title.strip()
    lower = topic.lower()
    # Prefer a focused explanation when the topic matches a well-known concept.
    explanation = next((value for key, value in TOPIC_NOTES.items() if key in lower), None)
    if explanation is None:
        explanation = (
            f"{topic} is an important topic in the {module} module of {course_name}. "
            f"Understand what problem it solves, the inputs it uses, the steps involved, "
            f"the expected output and the situations in which it should be applied. "
            f"Relate the concept to the wider workflow: {COURSE_CONTEXT.get(course_id, 'software development and problem solving')}"
        )
    example = COURSE_EXAMPLES.get(course_id, '')
    if course_id == 'sql-mysql' and any(k in lower for k in ('join', 'query', 'select', 'where', 'group', 'order')):
        example = "Example (SQL):\nSELECT e.name, d.department_name\nFROM employees AS e\nJOIN departments AS d ON d.id = e.department_id\nWHERE e.active = 1;"
    elif course_id == 'dsa-interview' and any(k in lower for k in ('binary search', 'search')):
        example = "Example (Python):\ndef binary_search(a, target):\n    left, right = 0, len(a) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if a[mid] == target: return mid\n        if a[mid] < target: left = mid + 1\n        else: right = mid - 1\n    return -1\n\n# Requires sorted input; O(log n) time."
    elif course_id == 'software-testing' and any(k in lower for k in ('api', 'http', 'status')):
        example = "Example test checklist:\n1. Send a valid request and verify the success status.\n2. Send missing or invalid data and verify validation errors.\n3. Check response fields, data types and headers.\n4. Verify unauthorized access is rejected."
    # Keep every lesson useful even when it is conceptual rather than code-heavy.
    return f"""{topic}\n{'=' * min(len(topic), 60)}\n\nLESSON OVERVIEW\nThis lesson is part of {course_name} ({module}). It focuses on {topic.lower()} and explains how the concept fits into practical development work.\n\nDETAILED EXPLANATION\n{explanation}\n\nKEY POINTS TO REMEMBER\n• Identify the purpose of {topic.lower()} and the problem it solves.\n• Understand its main components, rules and expected behavior.\n• Check valid inputs, invalid inputs and boundary cases.\n• Consider readability, correctness, performance, security and maintainability where relevant.\n• Use a small example first, then apply the idea to a realistic task.\n\nPRACTICAL EXAMPLE\n{example}\n\nPRACTICAL APPLICATION\nIn a real project, apply {topic.lower()} as part of the {module} workflow. Start with a clear requirement, implement the smallest working example, test normal and edge cases, and document the result. For database or API work, also validate data and handle errors. For UI work, check usability and accessibility.\n\nINTERVIEW QUESTIONS\n1. What is {topic}?\n   Answer: {explanation}\n2. Where would you use {topic} in a real project?\n   Answer: Use it when the requirement matches the problem it is designed to solve; explain the input, process, output and one practical example.\n3. What should you consider while implementing it?\n   Answer: Correctness, edge cases, readability, performance and maintainability. Mention any prerequisites or limitations relevant to the topic.\n\nPRACTICE EXERCISE\n1. Explain {topic} in your own words in 3–5 sentences.\n2. Create a small example related to {module}.\n3. Test the example with at least one normal case and two edge or invalid cases.\n4. Write down the output and explain why it is correct.\n\nREVISION\nBe ready to define the topic, explain its working, demonstrate the example and discuss one real-world use case and one limitation."""

# Replace all generic placeholder descriptions with topic-specific study material.
for _course_id, _lessons in COURSE_LESSONS.items():
    for _lesson in _lessons:
        _lesson['content'] = _make_lesson_content(
            _course_id, _lesson.get('module', 'Course Topics'), _lesson.get('title', 'Lesson')
        )


def get_course_lessons(course_id):
    return [dict(lesson) for lesson in COURSE_LESSONS.get(course_id, [])]

def get_lesson(course_id, lesson_id):
    for lesson in COURSE_LESSONS.get(course_id, []):
        if lesson['id'] == lesson_id:
            return dict(lesson)
    return None

def get_total_lessons(course_id):
    return len(COURSE_LESSONS.get(course_id, []))

__all__ = ['COURSE_LESSONS', 'get_course_lessons', 'get_lesson', 'get_total_lessons']
